const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P(5,5)' },
      { kind: 'text', payload: '第一象限' },
      { kind: 'text', payload: '5' },
      { kind: 'text', payload: '5' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ox = Math.round(W * 0.18);
    var oy = Math.round(H * 0.86);
    var lenX = Math.round(W * 0.74);
    var lenY = Math.round(H * 0.72);
    var u = Math.min(lenX / 6.6, lenY / 6.6);
    var xEnd = ox + lenX;
    var yEnd = oy - lenY;
    var px = ox + 5 * u;
    var py = oy - 5 * u;
    var ink = '#26354a';
    var hot = '#c0392b';

    var paths = [
      { id: 'xaxis', commands: visualSdk.arrow(ox, oy, xEnd, oy) },
      { id: 'yaxis', commands: visualSdk.arrow(ox, oy, ox, yEnd) },
      { id: 'dashx', commands: visualSdk.polyline([[px, py], [px, oy]]) },
      { id: 'dashy', commands: visualSdk.polyline([[px, py], [ox, py]]) },
      { id: 'tickx', commands: visualSdk.polyline([[px, oy - 4], [px, oy + 4]]) },
      { id: 'ticky', commands: visualSdk.polyline([[ox - 4, py], [ox + 4, py]]) },
      { id: 'point', commands: visualSdk.circle(px, py, 4.5) }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'quadrant-i-point-p',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'xaxis', fill: ink, stroke: { width: 1.8 } },
          { type: 'path', pathId: 'yaxis', fill: ink, stroke: { width: 1.8 } },
          { type: 'path', pathId: 'dashx', fill: ink, stroke: { width: 1.4, dash: [6, 5] } },
          { type: 'path', pathId: 'dashy', fill: ink, stroke: { width: 1.4, dash: [6, 5] } },
          { type: 'path', pathId: 'tickx', fill: ink, stroke: { width: 1.4 } },
          { type: 'path', pathId: 'ticky', fill: ink, stroke: { width: 1.4 } },
          { type: 'path', pathId: 'point', fill: hot, stroke: { width: 1.5 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: ox - 10, y: yEnd + 6 }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: xEnd - 4, y: oy + 10 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: ox - 9, y: oy + 7 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: px + 10, y: py - 8 }, hAlign: 'left', vAlign: 'bottom', color: '#c0392b' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: ox + lenX * 0.62, y: yEnd + lenY * 0.10 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: px, y: oy + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: ox - 9, y: py }, hAlign: 'right', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
